11	  create(customer: unknown, amountCents: unknown): Order {
12	    if (typeof customer !== "string" || customer.trim() === "") {
13	      throw badRequest("INVALID_REQUEST", "customer is required");
14	    }
15	    if (!Number.isInteger(amountCents) || (amountCents as number) <= 0) {
16	      throw badRequest("INVALID_REQUEST", "amountCents must be a positive integer");
17	    }
18	    return this.orders.insert(customer.trim(), amountCents as number, this.clock().toISOString());
19	  }
