21	  get(id: number): Order {
22	    const order = this.orders.findById(id);
23	    if (!order) throw notFound("ORDER_NOT_FOUND", `order ${id} not found`);
24	    return order;
25	  }
26	
27	  list(): Order[] {
28	    return this.orders.list();
29	  }
30	
31	  pay(id: number): Order {
32	    const order = this.get(id);
33	    if (order.status !== "PENDING") throw conflict("ORDER_NOT_PENDING", `order ${id} is ${order.status}`);
34	    this.orders.updateStatus(id, "PAID");
35	    return this.get(id);
36	  }
37	
38	  cancel(id: number): Order {
39	    const order = this.get(id);
40	    if (order.status !== "PENDING") throw conflict("ORDER_NOT_PENDING", `order ${id} is ${order.status}`);
41	    this.orders.updateStatus(id, "CANCELLED");
42	    return this.get(id);
