      (app) => {
        app.request("POST", "/orders/1/apply-coupon", { couponCode: 42 });
        return 0;
      },
    ],
    [
      "blank code",
      400,
      "INVALID_REQUEST",
      (app) => {
        app.request("POST", "/orders/1/apply-coupon", { couponCode: "   " });
        return 0;
      },
    ],
